INSERT INTO exp_rings (position,ring_key,ring_name,legacy_key,seo_function,schema_types,schema_properties,edge_properties,notes) VALUES
(1,'identity','Identity','core_identity','Entity disambiguation — who/what this is, exactly and uniquely',ARRAY['Person','Organization','LocalBusiness','Corporation']::text[],ARRAY['name','legalName','alternateName','description','disambiguatingDescription','logo','image','photo','url','telephone','email','faxNumber','openingHours','openingHoursSpecification','specialOpeningHoursSpecification','priceRange','currenciesAccepted','paymentAccepted','identifier','duns','taxID','naics','vatID','leiCode','iso6523Code','globalLocationNumber','tickerSymbol','foundingDate','dissolutionDate','numberOfEmployees','slogan','jobTitle','honorificPrefix','honorificSuffix','givenName','familyName','additionalName','gender','birthDate','nationality','branchCode','contactPoint','contactPoints','vehicleIdentificationNumber']::text[],ARRAY['@id']::text[],'Public co = Corporation+tickerSymbol; private = Organization+legalName/taxID. Person = the professional entity for route-to-market categories.'),
(2,'presence','Presence','profiles_presence','Citation coverage and consistency — every place the entity verifiably exists',ARRAY['ProfilePage','WebPage']::text[],ARRAY['sameAs','mainEntityOfPage','subjectOf']::text[],ARRAY['sameAs']::text[],'One sameAs edge per listing. ProfilePage.mainEntity -> the entity is the Experience.com pattern.'),
(3,'location','Location',NULL,'Geographic relevance — the dominant local-search ranking dimension',ARRAY['Place','PostalAddress','GeoCoordinates','GeoShape']::text[],ARRAY['address','geo','latitude','longitude','areaServed','serviceArea','hasMap','location','containedInPlace','containsPlace']::text[],ARRAY['areaServed','containedInPlace']::text[],'Storefront point vs service-area polygon; multi-market coverage. NEW ring — promoted from Identity/Context split.'),
(4,'authority','Authority','verifiable_authority','Provable expertise — E-E-A-T trust plus expertise clustering',ARRAY['EducationalOccupationalCredential','Occupation','ProgramMembership','DefinedTerm','DefinedTermSet']::text[],ARRAY['hasCredential','hasCertification','credentialCategory','recognizedBy','validIn','alumniOf','award','awards','hasOccupation','knowsAbout','knowsLanguage','qualifications','skills','occupationalCategory','yearsInOperation']::text[],ARRAY['recognizedBy','memberOf']::text[],'knowsAbout targets DefinedTerm nodes (VA Loans, Luxury Homes) — expertise clustering is the moat mechanism. License numbers via identifier+PropertyValue.'),
(5,'services','Services',NULL,'Query-intent match — what the entity does, offers, and sells',ARRAY['Service','OfferCatalog','Offer','Product']::text[],ARRAY['hasOfferCatalog','makesOffer','availableService','serviceType','availableChannel','hoursAvailable','providerMobility','audience','medicalSpecialty']::text[],ARRAY['provider','itemOffered']::text[],'The binding point for logic-layer value_props/search_intents. NEW ring — promoted out of Content/Transactions.'),
(6,'content','Content','published_content','Freshness, topical relevance, demonstrated expertise (absorbs media/voice)',ARRAY['CreativeWork','Article','BlogPosting','NewsArticle','FAQPage','Question','Answer','HowTo','VideoObject','ImageObject','AudioObject']::text[],ARRAY['about','mentions','keywords','datePublished','dateModified','headline','articleBody','inLanguage','acceptedAnswer','hasMenu','menu','hasMenuItem','hasMenuSection','hasCourse','servesCuisine','amenityFeature','starRating','petsAllowed','smokingAllowed','isAccessibleForFree','publicAccess','tourBookingPage','publishingPrinciples','itemListElement']::text[],ARRAY['author','creator','publisher','isPartOf']::text[],'author @id = the authored-by E-E-A-T edge back to the Person.'),
(7,'reputation','Reputation',NULL,'Social proof — what others verifiably say',ARRAY['AggregateRating','Review','Rating']::text[],ARRAY['aggregateRating','review','reviews','reviewedBy','ratingValue','reviewCount','ratingCount','bestRating','reviewRating','reviewBody','reviewAspect']::text[],ARRAY['author','publisher','itemReviewed']::text[],'publisher @id distinguishes GMB vs Healthgrades vs Yelp review provenance. Reputation is genuinely new (legacy_key NULL); old media_voice nodes group under Content in UI.'),
(8,'engagement','Engagement','social_engagement','Liveness and popularity signals',ARRAY['InteractionCounter','FollowAction','CommunicateAction','SubscribeAction']::text[],ARRAY['interactionStatistic','agentInteractionStatistic','interactionType','userInteractionCount','interactionService','follows']::text[],ARRAY[]::text[],'interactionStatistic=received vs agentInteractionStatistic=performed.'),
(9,'conversion','Conversion','transactions_outcomes','Outcome proof — hardest signal to fake; ties to conversion_actions',ARRAY['Order','Reservation','FoodEstablishmentReservation','LodgingReservation','Demand','OrderAction','ReserveAction','ScheduleAction','BuyAction','PayAction','RegisterAction']::text[],ARRAY['potentialAction','seeks','acceptsReservations','hasPOS','paymentMethod','acceptedPaymentMethod','checkinTime','checkoutTime','numberOfRooms','occupancy','availability','price','priceCurrency']::text[],ARRAY['potentialAction']::text[],'potentialAction wires conversion_actions into the graph. Mostly platform-observed -> trust tier matters. CommunicateAction (NOT ContactAction — doesn''t exist) lives in Engagement.'),
(10,'entity_graph','Entity Graph','upstream_context','AI connectivity — how models situate the entity among entities',ARRAY['Brand']::text[],ARRAY['parentOrganization','subOrganization','department','brand','owns','funder','sponsor','memberOf','member','members','affiliation','worksFor','employee','employees','founder','founders','colleague','parent','children','spouse','knows','relatedTo','isPartOf','hasPart','branchOf','ownershipFundingInfo']::text[],ARRAY['parentOrganization','memberOf','brand','worksFor','sameAs']::text[],'parentOrganization = OWNERSHIP ONLY; franchisee = brand + memberOf, never parentOrganization. sameAs here targets knowledge bases. about/mentions edges from Content point INTO this ring.');